-- Field work records: nutrient master data of products (ADR-010), a shared fertilizer catalogue,
-- and the plant-protection register of the BVL (approvals, approved uses, crop groups).

-- ---------------------------------------------------------------------------
-- Product nutrient data
-- ---------------------------------------------------------------------------

-- All contents are % of fresh mass (kg per 100 kg), for mineral and organic fertilizers alike;
-- an organic analysis in kg/t or kg/m³ is converted on entry. Density converts volumes to mass.
ALTER TABLE products
  ADD COLUMN nh4_n_pct      numeric(6, 3) CHECK (nh4_n_pct BETWEEN 0 AND 100),
  ADD COLUMN mgo_pct        numeric(6, 3) CHECK (mgo_pct BETWEEN 0 AND 100),
  -- Lime value in kg CaO per 100 kg; negative for acidifying fertilizers.
  ADD COLUMN cao_pct        numeric(6, 3) CHECK (cao_pct BETWEEN -100 AND 100),
  ADD COLUMN dry_matter_pct numeric(6, 3) CHECK (dry_matter_pct BETWEEN 0 AND 100),
  ADD COLUMN density_t_m3   numeric(8, 4) CHECK (density_t_m3 > 0 AND density_t_m3 < 5),
  -- Nitrogen form of a mineral fertilizer or the kind of organic fertilizer. Decides the minimum
  -- N efficiency (DüV Anlage 3), the 170 kg N limit and the emission factors.
  ADD COLUMN fertilizer_type text CHECK (fertilizer_type IN (
    'can', 'urea', 'urea_inhibitor', 'uan', 'np', 'npk', 'pk', 'other_mineral',
    'cattle_slurry', 'pig_slurry', 'cattle_liquid_manure', 'pig_liquid_manure', 'cattle_solid_manure',
    'pig_solid_manure', 'horse_sheep_manure', 'poultry_manure', 'laying_hen_dry_manure',
    'digestate_liquid', 'digestate_solid', 'compost', 'sewage_sludge', 'other_organic')),
  ADD COLUMN catalogue_entry_id uuid;

-- ---------------------------------------------------------------------------
-- Fertilizer catalogue (shared reference data)
-- ---------------------------------------------------------------------------

-- Typical analyses of mineral fertilizers and standard values of organic fertilizers by dry
-- matter content, ported from AGVOLUTION/agmeo (scripts/generate-fertilizer-catalogue.py).
-- Organizations copy an entry into their products and may correct it with their own analysis.
CREATE TABLE fertilizer_catalogue (
  id                uuid PRIMARY KEY DEFAULT uuidv7(),
  source_key        text NOT NULL UNIQUE,
  name_de           text NOT NULL,
  name_en           text NOT NULL,
  fertilizer_type   text NOT NULL,
  state             text NOT NULL CHECK (state IN ('solid', 'liquid')),
  suggested_unit    text NOT NULL CHECK (suggested_unit IN ('kg', 't', 'l', 'm3')),
  n_pct             numeric(6, 3),
  nh4_n_pct         numeric(6, 3),
  p2o5_pct          numeric(6, 3),
  k2o_pct           numeric(6, 3),
  mgo_pct           numeric(6, 3),
  cao_pct           numeric(6, 3),
  dry_matter_pct    numeric(6, 3),
  density_t_m3      numeric(8, 4),
  -- EUR per suggested unit; indicative only.
  indicative_price  numeric(12, 4)
);
CREATE INDEX fertilizer_catalogue_name_idx ON fertilizer_catalogue (lower(name_de) text_pattern_ops);

ALTER TABLE products ADD CONSTRAINT products_catalogue_entry_fkey
  FOREIGN KEY (catalogue_entry_id) REFERENCES fertilizer_catalogue (id) ON DELETE SET NULL;

