-- ---------------------------------------------------------------------------
-- Plant-protection register of the BVL (shared reference data)
-- ---------------------------------------------------------------------------

-- Refreshed by `pnpm sync:psm` from the BVL's public PSM API, with the agmeo_refdata role.
-- Products are matched to an organization's products by registration number (Zulassungsnummer).
CREATE TABLE psm_products (
  kennr              text PRIMARY KEY,
  name               text NOT NULL,
  formulation        text,
  first_approved_on  date,
  approval_ends_on   date,
  -- Products whose approval ended may be sold and used until these dates.
  sale_until         date,
  use_up_until       date,
  -- [{"name": "Tebuconazol", "content": 250, "unit": "g/l"}]
  active_ingredients jsonb NOT NULL DEFAULT '[]'::jsonb,
  synced_at          timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX psm_products_name_idx ON psm_products (lower(name) text_pattern_ops);

-- One approved use (Anwendungsgebiet, AWG) of a product.
CREATE TABLE psm_uses (
  awg_id                text PRIMARY KEY,
  kennr                 text NOT NULL REFERENCES psm_products (kennr) ON DELETE CASCADE,
  -- Professional use; false for uses approved for home and allotment gardens only.
  professional          boolean NOT NULL,
  area                  text,
  -- EPPO codes of the crops (or crop groups) the use is approved for, and those excluded.
  crop_codes            text[] NOT NULL DEFAULT '{}',
  excluded_crop_codes   text[] NOT NULL DEFAULT '{}',
  target_codes          text[] NOT NULL DEFAULT '{}',
  bbch_from             smallint,
  bbch_to               smallint,
  max_applications      smallint,
  min_interval_days     smallint,
  max_interval_days     smallint,
  -- Highest approved product dose and its BVL unit code (LH, KH, CH, GH, …).
  dose_max              numeric(14, 4),
  dose_unit             text,
  water_min_l_ha        numeric(10, 2),
  water_max_l_ha        numeric(10, 2),
  -- Pre-harvest interval in days by crop code: {"TRZAW": 35}. A null value means the
  -- interval is covered by the application window ("F").
  waiting_days          jsonb NOT NULL DEFAULT '{}'::jsonb,
  synced_at             timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX psm_uses_kennr_idx ON psm_uses (kennr);
CREATE INDEX psm_uses_crops_idx ON psm_uses USING gin (crop_codes);

-- BVL crop hierarchy: a group code (e.g. TRZSS, wheat) and the codes it contains.
CREATE TABLE psm_crop_groups (
  group_code  text NOT NULL,
  member_code text NOT NULL,
  PRIMARY KEY (group_code, member_code)
);
CREATE INDEX psm_crop_groups_member_idx ON psm_crop_groups (member_code);

-- Texts of BVL codes (crops, pests, units) in German.
CREATE TABLE psm_codes (
  code text NOT NULL,
  list smallint NOT NULL,
  text text NOT NULL,
  PRIMARY KEY (code, list)
);

-- The codes a crop's EPPO code is covered by: itself and every group above it.
CREATE FUNCTION app.psm_crop_ancestors(eppo text) RETURNS text[]
LANGUAGE sql STABLE AS $$
  WITH RECURSIVE up(code) AS (
    SELECT eppo
    UNION
    SELECT g.group_code FROM psm_crop_groups g JOIN up ON g.member_code = up.code
  )
  SELECT coalesce(array_agg(code), ARRAY[eppo]) FROM up
$$;

GRANT SELECT ON fertilizer_catalogue, psm_products, psm_uses, psm_crop_groups, psm_codes TO agmeo_app;
GRANT EXECUTE ON FUNCTION app.psm_crop_ancestors(text) TO agmeo_app, agmeo_refdata;
GRANT SELECT, INSERT, UPDATE, DELETE ON fertilizer_catalogue, psm_products, psm_uses, psm_crop_groups, psm_codes TO agmeo_refdata;
GRANT SELECT (eppo_code) ON crops TO agmeo_refdata;
